def intersection(interval1, interval2):
    """
    Given two closed integer intervals [a1, b1] and [a2, b2],
    find the length of their intersection.
    If the length is a prime number, return "YES", else "NO".
    If there is no intersection, return "NO".
    """
    # Ensure consistent ordering: [min(a1, a2), max(b1, b2)]
    a1, b1 = interval1
    a2, b2 = interval2

    start = min(a1, a2)
    end = max(b1, b2)

    # No intersection if start > end
    if start > end:
        return "NO"

    # Length of intersection
    length = end - start

    # Check if length is prime
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        i = 3
        while i * i <= n:
            if n % i == 0:
                return False
            i += 2
        return True

    if is_prime(length):
        return "YES"
    else:
        return "NO"

