def monotonic(l: list):
    """Return True if list elements are monotonically increasing or decreasing.
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    """
    if len(l) <= 1:
        return True

    # Check for strictly increasing
    for i in range(len(l) - 1):
        if l[i] >= l[i + 1]:
            return False

    # Check for strictly decreasing
    for i in range(len(l) - 1):
        if l[i] <= l[i + 1]:
            return False

    return True

